"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6439],{66439:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/a-night-of-murder-without-a-perpetrator.png\\"\\n          title=\\"범인 없는 살인의 밤\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"랜덤하우스코리아\\"\\n          publishedDate=\\"2009-04-16\\"\\n          isbn=\\"9788925532172\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n작가의 초기 단편집으로 <mark>사소한 악의</mark>가 어떻게 파국적인 결과를 낳는가라는 하나의 강력한 주제를 가지고 있다.  \\n거대한 음모나 사이코패스적인 악인이 아닌, 우리 주변에서 흔히 볼 수 있는 평범한 인물들의 내면에 깃든 ```악의 평범성```을 탐구한다.  \\n<br>\\n<mark>아주 작은 고의</mark>가 어떻게 나비효과처럼 증폭되어 돌이킬 수 없는 비극으로 치닫는 것을 추적한다.  \\n겉보기에는 평범하고 선량한 인간이라 할지라도 내면에는 얼마든지 잔인한 파괴의 씨앗을 품고 있음을 보여준다.  \\n<br>\\n작가의 초기 작품이라 설정상 무리나 거친 전개의 ```어설픔```이 느껴지기도 한다."}')}}]);